import { useEffect, useState } from 'react';
import { CalendarDays, Home, Plus, Settings } from 'lucide-react';
import { db, isCloudStorageEnabled } from './lib/coralred-storage.js';
import {
  ReservationData,
  ReservationDoc,
  ReservationStatus,
  addDays,
  buildSampleReservations,
  toDateKey,
} from './lib/salon';
import { HomeView } from './components/HomeView';
import { WeekView } from './components/WeekView';
import { RegisterView } from './components/RegisterView';
import { DetailSheet } from './components/DetailSheet';
import { SettingsSheet } from './components/SettingsSheet';
import { Toast } from './components/Toast';

type Tab = 'home' | 'week' | 'register';

function App() {
  const todayKey = toDateKey(new Date());

  const [items, setItems] = useState<ReservationDoc[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState('');
  const [tab, setTab] = useState<Tab>('home');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [salonName, setSalonName] = useState('스타일 살롱');
  const [anchorDate, setAnchorDate] = useState(new Date());
  const [selectedDateKey, setSelectedDateKey] = useState(todayKey);
  const [toast, setToast] = useState('');

  function notify(message: string) {
    setToast(message);
    window.setTimeout(() => setToast(''), 2200);
  }

  async function load() {
    setLoading(true);
    setLoadError('');

    try {
      let { items: docs } = await db.list('reservations', { limit: 100 });

      if (docs.length === 0) {
        const seeds = buildSampleReservations();
        const created = [];
        for (const seed of seeds) {
          created.push(await db.create('reservations', seed));
        }
        docs = created;
      }

      setItems(docs as ReservationDoc[]);
    } catch (err) {
      setLoadError(err instanceof Error ? err.message : '불러오다가 문제가 생겼어요.');
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, []);

  async function handleCreate(data: ReservationData) {
    const created = (await db.create('reservations', data)) as ReservationDoc;
    setItems((prev) => [created, ...prev]);
    notify(`${data.customerName}님 예약을 등록했어요`);
    setTab('home');
  }

  async function handleChangeStatus(id: string, status: ReservationStatus) {
    const target = items.find((r) => r.id === id);
    if (!target) return;

    const next = { ...target.data, status };
    setItems((prev) => prev.map((r) => (r.id === id ? { ...r, data: next } : r)));

    try {
      await db.update('reservations', id, next);
      notify('예약 상태를 바꿨어요');
    } catch (err) {
      setItems((prev) => prev.map((r) => (r.id === id ? target : r)));
      notify(err instanceof Error ? err.message : '바꾸지 못했어요');
    }
  }

  async function handleDelete(id: string) {
    const target = items.find((r) => r.id === id);
    setItems((prev) => prev.filter((r) => r.id !== id));
    setSelectedId(null);

    try {
      await db.remove('reservations', id);
      notify('예약을 지웠어요');
    } catch (err) {
      if (target) setItems((prev) => [target, ...prev]);
      notify(err instanceof Error ? err.message : '지우지 못했어요');
    }
  }

  async function handleClearSamples() {
    const snapshot = items;
    setItems([]);
    setSettingsOpen(false);

    try {
      for (const r of snapshot) {
        await db.remove('reservations', r.id);
      }
      notify('예시 데이터를 지웠어요');
    } catch (err) {
      setItems(snapshot);
      notify(err instanceof Error ? err.message : '지우지 못했어요');
    }
  }

  const selectedDoc = items.find((r) => r.id === selectedId) ?? null;

  return (
    <div className="salon-app">
      <header className="salon-header">
        <div className="cr-page salon-header-inner">
          <div className="cr-stack-4">
            <span className="cr-eyebrow">{salonName}</span>
            <span className="cr-caption salon-muted">예약 관리</span>
          </div>
          <button
            type="button"
            className="cr-btn ghost"
            onClick={() => setSettingsOpen(true)}
            aria-label="설정 열기"
          >
            <Settings size={20} />
          </button>
        </div>
      </header>

      <main className="cr-page salon-main">
        {!isCloudStorageEnabled && (
          <span className="cr-badge warn salon-cloud-note">데이터가 이 기기에만 저장돼요</span>
        )}

        {loading ? (
          <div className="cr-stack-16 salon-skeleton-wrap">
            <div className="salon-skeleton salon-skeleton-title" />
            <div className="cr-grid-3">
              <div className="salon-skeleton salon-skeleton-card" />
              <div className="salon-skeleton salon-skeleton-card" />
              <div className="salon-skeleton salon-skeleton-card" />
            </div>
            <div className="salon-skeleton salon-skeleton-row" />
            <div className="salon-skeleton salon-skeleton-row" />
            <div className="salon-skeleton salon-skeleton-row" />
          </div>
        ) : loadError ? (
          <div className="cr-card salon-empty cr-stack-16">
            <p className="cr-body">{loadError}</p>
            <button type="button" className="cr-btn" onClick={load}>
              다시 시도하기
            </button>
          </div>
        ) : (
          <div key={tab} className="salon-fade">
            {tab === 'home' && (
              <HomeView
                items={items}
                todayKey={todayKey}
                onSelect={setSelectedId}
                onGoRegister={() => setTab('register')}
              />
            )}
            {tab === 'week' && (
              <WeekView
                items={items}
                anchorDate={anchorDate}
                selectedKey={selectedDateKey}
                todayKey={todayKey}
                onShiftWeek={(delta) => setAnchorDate((d) => addDays(d, delta))}
                onSelectDate={setSelectedDateKey}
                onSelect={setSelectedId}
              />
            )}
            {tab === 'register' && (
              <RegisterView defaultDate={todayKey} onSubmit={handleCreate} />
            )}
          </div>
        )}
      </main>

      <nav className="salon-tabbar" aria-label="주요 화면">
        <button
          type="button"
          className={`salon-tab${tab === 'home' ? ' salon-tab-on' : ''}`}
          onClick={() => setTab('home')}
        >
          <Home size={20} />
          <span className="cr-caption">오늘</span>
        </button>
        <button
          type="button"
          className={`salon-tab${tab === 'week' ? ' salon-tab-on' : ''}`}
          onClick={() => setTab('week')}
        >
          <CalendarDays size={20} />
          <span className="cr-caption">주간</span>
        </button>
        <button
          type="button"
          className={`salon-tab${tab === 'register' ? ' salon-tab-on' : ''}`}
          onClick={() => setTab('register')}
        >
          <Plus size={20} />
          <span className="cr-caption">등록</span>
        </button>
      </nav>

      {selectedDoc && (
        <DetailSheet
          doc={selectedDoc}
          onClose={() => setSelectedId(null)}
          onChangeStatus={handleChangeStatus}
          onDelete={handleDelete}
        />
      )}

      {settingsOpen && (
        <SettingsSheet
          salonName={salonName}
          onChangeName={setSalonName}
          onClearSamples={handleClearSamples}
          onClose={() => setSettingsOpen(false)}
        />
      )}

      {toast && <Toast message={toast} />}
    </div>
  );
}

export default App;

