export type ReservationStatus = 'confirmed' | 'pending' | 'canceled' | 'done';

export interface ReservationData {
  customerName: string;
  phone: string;
  date: string;
  startTime: string;
  durationMin: number;
  service: string;
  price: number;
  status: ReservationStatus;
  memo?: string;
}

export interface ReservationDoc {
  id: string;
  data: ReservationData;
  createdAt: string;
  updatedAt: string;
}

export const SERVICES = [
  { name: '커트', durationMin: 40, price: 25000 },
  { name: '펌', durationMin: 120, price: 90000 },
  { name: '염색', durationMin: 100, price: 80000 },
  { name: '클리닉', durationMin: 60, price: 55000 },
  { name: '드라이', durationMin: 30, price: 20000 },
];

export const STATUS_LABEL: Record<ReservationStatus, string> = {
  confirmed: '확정',
  pending: '대기',
  canceled: '취소',
  done: '완료',
};

export const STATUS_BADGE: Record<ReservationStatus, string> = {
  confirmed: 'cr-badge ok',
  pending: 'cr-badge warn',
  canceled: 'cr-badge err',
  done: 'cr-badge',
};

export const OPEN_HOUR = 10;
export const CLOSE_HOUR = 20;

export function toDateKey(d: Date) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

export function addDays(d: Date, n: number) {
  const next = new Date(d);
  next.setDate(next.getDate() + n);
  return next;
}

export function formatKoreanDate(key: string) {
  const [y, m, d] = key.split('-').map(Number);
  const date = new Date(y, m - 1, d);
  const weekday = ['일', '월', '화', '수', '목', '금', '토'][date.getDay()];
  return `${m}월 ${d}일 (${weekday})`;
}

export function formatWon(n: number) {
  return `${n.toLocaleString('ko-KR')}원`;
}

export function timeToMinutes(time: string) {
  const [h, m] = time.split(':').map(Number);
  return h * 60 + m;
}

export function minutesToTime(min: number) {
  const h = Math.floor(min / 60);
  const m = min % 60;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

export function endTimeOf(r: ReservationData) {
  return minutesToTime(timeToMinutes(r.startTime) + r.durationMin);
}

/** 영업시간 내 30분 슬롯 중 예약이 없는 칸 수 */
export function countFreeSlots(items: ReservationDoc[], dateKey: string) {
  const busy = new Set<number>();

  items
    .filter((r) => r.data.date === dateKey && r.data.status !== 'canceled')
    .forEach((r) => {
      const start = timeToMinutes(r.data.startTime);
      for (let t = start; t < start + r.data.durationMin; t += 30) {
        busy.add(t - (t % 30));
      }
    });

  let free = 0;
  for (let t = OPEN_HOUR * 60; t < CLOSE_HOUR * 60; t += 30) {
    if (!busy.has(t)) free += 1;
  }
  return free;
}

export function buildSampleReservations(): ReservationData[] {
  const today = new Date();
  const t = toDateKey(today);
  const tomorrow = toDateKey(addDays(today, 1));
  const past = (n: number) => toDateKey(addDays(today, -n));

  return [
    { customerName: '김서연', phone: '010-2837-1102', date: t, startTime: '10:00', durationMin: 40, service: '커트', price: 25000, status: 'confirmed', memo: '앞머리 짧게' },
    { customerName: '박지훈', phone: '010-4471-2093', date: t, startTime: '11:00', durationMin: 120, service: '펌', price: 90000, status: 'confirmed' },
    { customerName: '이하늘', phone: '010-9920-3345', date: t, startTime: '14:00', durationMin: 100, service: '염색', price: 80000, status: 'pending', memo: '색상 상담 필요' },
    { customerName: '최윤아', phone: '010-3382-7710', date: t, startTime: '16:00', durationMin: 60, service: '클리닉', price: 55000, status: 'confirmed' },
    { customerName: '정민재', phone: '010-5518-8842', date: t, startTime: '18:00', durationMin: 30, service: '드라이', price: 20000, status: 'canceled' },

    { customerName: '한소미', phone: '010-7743-1120', date: tomorrow, startTime: '10:30', durationMin: 40, service: '커트', price: 25000, status: 'confirmed' },
    { customerName: '오세진', phone: '010-2210-6634', date: tomorrow, startTime: '13:00', durationMin: 100, service: '염색', price: 80000, status: 'pending' },
    { customerName: '윤가은', phone: '010-8890-4417', date: tomorrow, startTime: '15:30', durationMin: 120, service: '펌', price: 90000, status: 'confirmed' },

    { customerName: '강태윤', phone: '010-3345-9982', date: past(2), startTime: '11:00', durationMin: 40, service: '커트', price: 25000, status: 'done' },
    { customerName: '문지아', phone: '010-6612-3308', date: past(3), startTime: '14:30', durationMin: 60, service: '클리닉', price: 55000, status: 'done' },
