import { CalendarCheck, Clock3, Scissors, ChevronRight } from 'lucide-react';
import {
  ReservationDoc,
  ReservationStatus,
  STATUS_LABEL,
  STATUS_BADGE,
  OPEN_HOUR,
  CLOSE_HOUR,
  countFreeSlots,
  endTimeOf,
  formatKoreanDate,
  formatWon,
  timeToMinutes,
} from '../lib/salon';

interface HomeViewProps {
  items: ReservationDoc[];
  todayKey: string;
  onSelect: (id: string) => void;
  onGoRegister: () => void;
}

export function HomeView({ items, todayKey, onSelect, onGoRegister }: HomeViewProps) {
  const todayItems = items
    .filter((r) => r.data.date === todayKey)
    .sort((a, b) => timeToMinutes(a.data.startTime) - timeToMinutes(b.data.startTime));

  const activeToday = todayItems.filter((r) => r.data.status !== 'canceled');
  const freeSlots = countFreeSlots(items, todayKey);
  const expectedSales = activeToday.reduce((sum, r) => sum + r.data.price, 0);

  const statusCount = (s: ReservationStatus) =>
    todayItems.filter((r) => r.data.status === s).length;

  return (
    <div className="cr-stack-24">
      <div className="cr-stack-4">
        <span className="cr-eyebrow">TODAY</span>
        <h2 className="cr-h2">{formatKoreanDate(todayKey)} 예약 현황</h2>
      </div>

      <div className="cr-grid-3">
        <div className="cr-card salon-metric">
          <div className="cr-row-8 salon-metric-head">
            <CalendarCheck size={16} />
            <span className="cr-caption">오늘 예약</span>
          </div>
          <strong className="salon-metric-value">{activeToday.length}건</strong>
          <span className="cr-caption salon-muted">
            확정 {statusCount('confirmed')} · 대기 {statusCount('pending')} · 취소{' '}
            {statusCount('canceled')}
          </span>
        </div>

        <div className="cr-card salon-metric">
          <div className="cr-row-8 salon-metric-head">
            <Clock3 size={16} />
            <span className="cr-caption">빈 시간</span>
          </div>
          <strong className="salon-metric-value">{freeSlots}칸</strong>
          <span className="cr-caption salon-muted">
            {OPEN_HOUR}시–{CLOSE_HOUR}시 · 30분 단위
          </span>
        </div>

        <div className="cr-card salon-metric">
          <div className="cr-row-8 salon-metric-head">
            <Scissors size={16} />
            <span className="cr-caption">예상 매출</span>
          </div>
          <strong className="salon-metric-value">{formatWon(expectedSales)}</strong>
          <span className="cr-caption salon-muted">취소 건 제외</span>
        </div>
      </div>

