import { ChevronLeft, ChevronRight } from 'lucide-react';
import {
  ReservationDoc,
  STATUS_BADGE,
  STATUS_LABEL,
  addDays,
  countFreeSlots,
  endTimeOf,
  formatKoreanDate,
  timeToMinutes,
  toDateKey,
} from '../lib/salon';

interface WeekViewProps {
  items: ReservationDoc[];
  anchorDate: Date;
  selectedKey: string;
  todayKey: string;
  onShiftWeek: (delta: number) => void;
  onSelectDate: (key: string) => void;
  onSelect: (id: string) => void;
}

export function WeekView({
  items,
  anchorDate,
  selectedKey,
  todayKey,
  onShiftWeek,
  onSelectDate,
  onSelect,
}: WeekViewProps) {
  const start = addDays(anchorDate, -anchorDate.getDay());
  const days = Array.from({ length: 7 }, (_, i) => addDays(start, i));

  const maxCount = Math.max(
    1,
    ...days.map(
      (d) =>
        items.filter((r) => r.data.date === toDateKey(d) && r.data.status !== 'canceled').length,
    ),
  );

  const dayItems = items
    .filter((r) => r.data.date === selectedKey)
    .sort((a, b) => timeToMinutes(a.data.startTime) - timeToMinutes(b.data.startTime));

  return (
    <div className="cr-stack-24">
      <div className="cr-stack-4">
        <span className="cr-eyebrow">WEEK</span>
        <h2 className="cr-h2">주간 예약 분포</h2>
      </div>

      <div className="cr-card cr-stack-16">
        <div className="salon-week-nav">
          <button
            type="button"
            className="cr-btn ghost"
            onClick={() => onShiftWeek(-7)}
            aria-label="지난주"
          >
            <ChevronLeft size={16} />
          </button>
          <span className="cr-caption salon-muted">
            {formatKoreanDate(toDateKey(days[0]))} – {formatKoreanDate(toDateKey(days[6]))}
          </span>
          <button
            type="button"
            className="cr-btn ghost"
            onClick={() => onShiftWeek(7)}
            aria-label="다음주"
          >
            <ChevronRight size={16} />
          </button>
        </div>

        <div className="salon-week-grid">
          {days.map((d) => {
            const key = toDateKey(d);
            const count = items.filter(
              (r) => r.data.date === key && r.data.status !== 'canceled',
            ).length;
            const free = countFreeSlots(items, key);
            const isSelected = key === selectedKey;

            return (
              <button
                key={key}
                type="button"
                className={`salon-day${isSelected ? ' salon-day-on' : ''}`}
                onClick={() => onSelectDate(key)}
              >
                <span className="cr-caption salon-muted">
