                <div className="salon-bar-track" aria-hidden="true">
                  <div
                    className="salon-bar-fill"
                    style={{ height: `${(count / maxCount) * 100}%` }}
                  />
                </div>
                <span className="cr-caption salon-day-count">{count}건</span>
                {key === todayKey && <span className="salon-today-dot" aria-label="오늘" />}
                <span className="cr-caption salon-muted salon-day-free">여유 {free}</span>
              </button>
            );
