import { useState } from 'react';
import { ReservationData, SERVICES, formatWon, minutesToTime, OPEN_HOUR, CLOSE_HOUR, toDateKey } from '../lib/salon';

interface RegisterViewProps {
  defaultDate: string;
  onSubmit: (data: ReservationData) => Promise<void>;
}

const TIME_OPTIONS = (() => {
  const out: string[] = [];
  for (let t = OPEN_HOUR * 60; t < CLOSE_HOUR * 60; t += 30) out.push(minutesToTime(t));
  return out;
})();

export function RegisterView({ defaultDate, onSubmit }: RegisterViewProps) {
  const [customerName, setCustomerName] = useState('');
  const [phone, setPhone] = useState('');
  const [date, setDate] = useState(defaultDate);
  const [startTime, setStartTime] = useState('10:00');
  const [serviceName, setServiceName] = useState(SERVICES[0].name);
  const [memo, setMemo] = useState('');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  const service = SERVICES.find((s) => s.name === serviceName) ?? SERVICES[0];

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!customerName.trim()) {
      setError('예약자 이름을 적어주세요.');
      return;
    }

    setSaving(true);
    setError('');

    try {
      await onSubmit({
        customerName: customerName.trim(),
        phone: phone.trim(),
        date,
        startTime,
        durationMin: service.durationMin,
        service: service.name,
        price: service.price,
        status: 'confirmed',
        memo: memo.trim() || undefined,
      });
      setCustomerName('');
      setPhone('');
      setMemo('');
    } catch (err) {
      setError(err instanceof Error ? err.message : '저장하다가 문제가 생겼어요.');
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="cr-stack-24">
      <div className="cr-stack-4">
        <span className="cr-eyebrow">NEW</span>
        <h2 className="cr-h2">예약 등록</h2>
      </div>

      <form className="cr-card cr-stack-16 salon-form" onSubmit={handleSubmit}>
        <div className="cr-grid-2">
          <div className="cr-stack-4">
            <label className="cr-label" htmlFor="name">예약자 이름</label>
            <input
              id="name"
              className="cr-input"
              value={customerName}
              onChange={(e) => setCustomerName(e.target.value)}
              placeholder="예: 김서연"
            />
          </div>
          <div className="cr-stack-4">
            <label className="cr-label" htmlFor="phone">연락처</label>
            <input
              id="phone"
              className="cr-input"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              placeholder="010-0000-0000"
            />
          </div>
        </div>

        <div className="cr-grid-2">
          <div className="cr-stack-4">
            <label className="cr-label" htmlFor="date">날짜</label>
            <input
              id="date"
              type="date"
              className="cr-input"
              value={date}
              min={toDateKey(new Date())}
              onChange={(e) => setDate(e.target.value)}
            />
          </div>
          <div className="cr-stack-4">
            <label className="cr-label" htmlFor="time">시작 시각</label>
            <select
              id="time"
              className="cr-input"
              value={startTime}
              onChange={(e) => setStartTime(e.target.value)}
            >
              {TIME_OPTIONS.map((t) => (
                <option key={t} value={t}>{t}</option>
              ))}
            </select>
          </div>
        </div>

        <div className="cr-stack-8">
          <span className="cr-label">시술 항목</span>
          <div className="salon-chips">
            {SERVICES.map((s) => (
              <button
                key={s.name}
                type="button"
                className={`salon-chip${s.name === serviceName ? ' salon-chip-on' : ''}`}
                onClick={() => setServiceName(s.name)}
              >
                {s.name}
              </button>
            ))}
          </div>
          <span className="cr-caption salon-muted">
            {service.durationMin}분 소요 · {formatWon(service.price)}
          </span>
        </div>

        <div className="cr-stack-4">
          <label className="cr-label" htmlFor="memo">메모 (선택)</label>
          <textarea
            id="memo"
            className="cr-input"
            rows={2}
            value={memo}
            onChange={(e) => setMemo(e.target.value)}
            placeholder="예: 앞머리 짧게"
          />
        </div>

        {error && <p className="cr-caption salon-error">{error}</p>}

        <button className="cr-btn cr-btn-lg" type="submit" disabled={saving}>
          {saving ? '저장 중...' : '예약 등록하기'}
        </button>
      </form>
    </div>
  );
}

