  grid-template-columns: repeat(3, 1fr);
  background: var(--bg);
  border-top: 1px solid var(--border);
}

.salon-tab {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-height: 64px;
  border: none;
  background: none;
  color: var(--muted);
  cursor: pointer;
  transition: color 180ms ease-out, background 180ms ease-out;
}

.salon-tab:hover {
  color: var(--text);
}

.salon-tab-on {
  color: var(--accent);
}

/* 토스트 */
.salon-toast {
  position: fixed;
  left: 50%;
  bottom: 96px;
  transform: translateX(-50%);
  z-index: 50;
  padding: 12px 20px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--card, var(--bg));
  animation: salon-slide-up 200ms ease-out;
  white-space: nowrap;
}

/* 스켈레톤 */
.salon-skeleton {
  border-radius: 10px;
  background: var(--border);
  animation: salon-pulse 1.2s ease-in-out infinite;
}

.salon-skeleton-title { height: 28px; width: 60%; }
.salon-skeleton-card { height: 108px; }
.salon-skeleton-row { height: 72px; }

@keyframes salon-pulse {
  0%, 100% { opacity: 0.5; }
  50% { opacity: 0.9; }
}

/* 전환 */
.salon-fade {
  animation: salon-fade-in 220ms ease-out;
}

.salon-stagger {
  animation: salon-rise 260ms ease-out both;
}

@keyframes salon-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes salon-rise {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes salon-slide-up {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}

/* 데스크톱 */
@media (min-width: 1024px) {
  .salon-app { padding-bottom: 0; }

  .salon-main {
    padding-top: 32px;
    padding-bottom: 64px;
  }

  .salon-tabbar {
    position: sticky;
    top: 0;
    bottom: auto;
    max-width: 1120px;
    margin: 0 auto;
    grid-template-columns: repeat(3, max-content);
    border-top: none;
    border-bottom: 1px solid var(--border);
  }

  .salon-tab {
    flex-direction: row;
    gap: 8px;
    padding: 0 24px;
    min-height: 52px;
  }

  .salon-backdrop { align-items: center; }
  .salon-sheet { border-radius: 12px; }
  .salon-toast { bottom: 32px; }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}
